def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header: The Range header value (e.g., "bytes=0-499")
        size: The total size of the resource in bytes

    Returns:
        A list of (start, end) inclusive byte offsets, or None if unsatisfiable/malformed.
    """
    if not header or not isinstance(header, str):
        return None

    # Check that it starts with "bytes="
    if not header.startswith("bytes="):
        return None

    range_spec = header[6:]  # Remove "bytes=" prefix

    if not range_spec:
        return None

    ranges = []

    for part in range_spec.split(","):
        part = part.strip()
        if not part:
            continue

        try:
            if "-" not in part:
                return None

            parts = part.split("-", 1)

            if len(parts) != 2:
                return None

            start_str, end_str = parts

            # Case 1: suffix range (e.g., "-500")
            if start_str == "":
                # Suffix length
                try:
                    suffix_length = int(end_str)
                except ValueError:
                    return None

                if suffix_length <= 0:
                    continue  # Unsatisfiable, skip this range

                # The last suffix_length bytes
                start = max(0, size - suffix_length)
                end = size - 1
                ranges.append((start, end))

            else:
                # Case 2: normal range (e.g., "0-499" or "500-")
                try:
                    start = int(start_str)
                except ValueError:
                    return None

                if start < 0:
                    continue  # Unsatisfiable, skip this range

                if end_str == "":
                    # Range from start to end of resource
                    if start >= size:
                        continue  # Unsatisfiable, skip this range
                    end = size - 1
                else:
                    try:
                        end = int(end_str)
                    except ValueError:
                        return None

                    if end < 0:
                        continue  # Unsatisfiable, skip this range

                    # Clamp end to last byte
                    if end >= size:
                        end = size - 1

                    # Check if start is at or past size (unsatisfiable)
                    if start >= size:
                        continue

                    # If start > end after clamping, unsatisfiable
                    if start > end:
                        continue

                ranges.append((start, end))

        except Exception:
            return None

    # If no valid ranges were found, return None
    if not ranges:
        return None

    return ranges
