class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}  # freq -> OrderedDict of keys (insertion order = recency)
        self.min_freq = 0

    def _update(self, key):
        freq = self.key_to_freq[key]
        del self.freq_to_keys[freq][key]
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        new_freq = freq + 1
        self.key_to_freq[key] = new_freq
        if new_freq not in self.freq_to_keys:
            from collections import OrderedDict
            self.freq_to_keys[new_freq] = OrderedDict()
        self.freq_to_keys[new_freq][key] = None

    def get(self, key):
        if self.capacity == 0 or key not in self.key_to_val:
            return -1
        self._update(key)
        return self.key_to_val[key]

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update(key)
            return

        if len(self.key_to_val) >= self.capacity:
            # Evict least frequently used, then least recently used among those
            from collections import OrderedDict
            min_freq_keys = self.freq_to_keys[self.min_freq]
            evicted_key, _ = min_freq_keys.popitem(last=False)  # FIFO for LRU within same freq
            if not min_freq_keys:
                del self.freq_to_keys[self.min_freq]
            del self.key_to_val[evicted_key]
            del self.key_to_freq[evicted_key]

        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        if 1 not in self.freq_to_keys:
            from collections import OrderedDict
            self.freq_to_keys[1] = OrderedDict()
        self.freq_to_keys[1][key] = None
        self.min_freq = 1
