def lis_length(a):
    if not a:
        return 0

    # tails[i] holds the smallest tail element for an increasing subsequence of length i+1
    tails = []

    for x in a:
        # Binary search for the first element in tails that is >= x
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid

        # If no element >= x is found, append x
        if lo == len(tails):
            tails.append(x)
        else:
            # Replace the first element >= x with x (to maintain smallest tail for that length)
            tails[lo] = x

    return len(tails)
