import re

def parse_duration(s):
    if not isinstance(s, str) or len(s) == 0:
        raise ValueError("Invalid duration")

    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:]

    if not s.startswith('P'):
        raise ValueError("Duration must start with P")

    s = s[1:]  # Remove 'P'

    if len(s) == 0:
        raise ValueError("At least one field must be present")

    # Split into date and time parts at 'T'
    if 'T' in s:
        t_idx = s.index('T')
        date_part = s[:t_idx]
        time_part = s[t_idx+1:]
        has_time = True
    else:
        date_part = s
        time_part = ''
        has_time = False

    # Parse date part: nY, nM, nD (in any order? No, ISO-8601 specifies order Y, M, D)
    years = 0.0
    months = 0.0
    days = 0.0

    if date_part:
        # Parse date components in order: Y, M, D
        pattern_date = r'^(?:(\d+(?:\.\d+)?)Y)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)D)?$'
        m = re.match(pattern_date, date_part)
        if not m:
            raise ValueError("Invalid date part in duration")
        if m.group(1):
            years = float(m.group(1))
        if m.group(2):
            months = float(m.group(2))
        if m.group(3):
            days = float(m.group(3))

    # Parse time part: nH, nM, nS (in order H, M, S)
    hours = 0.0
    minutes = 0.0
    seconds = 0.0

    if has_time and time_part:
        pattern_time = r'^(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?$'
        m = re.match(pattern_time, time_part)
        if not m:
            raise ValueError("Invalid time part in duration")
        if m.group(1):
            hours = float(m.group(1))
        if m.group(2):
            minutes = float(m.group(2))
        if m.group(3):
            seconds = float(m.group(3))
    elif has_time and not time_part:
        raise ValueError("T present but no time fields follow")

    # Check that at least one field is present
    if years == 0 and months == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        raise ValueError("At least one field must be present")

    # Convert to total seconds using 365 days/year, 30 days/month
    total_seconds = (years * 365 + months * 30 + days) * 24 * 3600 + hours * 3600 + minutes * 60 + seconds

    if negative:
        total_seconds = -total_seconds

    return float(total_seconds)
