from datetime import datetime, timedelta


def next_fire(expr: str, after: datetime) -> datetime:
    """
    Return the next datetime strictly after `after` at which the given 5-field cron expression fires.

    The cron expression has fields: minute hour day-of-month month day-of-week

    Raises ValueError on malformed expression.
    """
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minutes, hours, doms, months, dowss = [parse_field(p, i) for i, p in enumerate(parts)]

    # Determine which day fields are restricted
    dom_restricted = parts[2] != '*'
    dow_restricted = parts[4] != '*'

    # Start searching from the next minute after `after`
    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Search for up to 4 years ahead (reasonable limit)
    end_limit = after + timedelta(days=365 * 4 + 1)

    while candidate <= end_limit:
        # Check month
        if candidate.month not in months:
            # Skip to next valid month
            candidate = _skip_to_next_month(candidate, months)
            continue

        # Check day (dom and dow logic)
        if dom_restricted and dow_restricted:
            # Fire on EITHER matching
            if candidate.day not in doms and candidate.weekday() + 1 % 7 not in dowss:
                # Python weekday(): Monday=0, Sunday=6. Cron: Sunday=0, Saturday=6
                cron_dow = (candidate.weekday() + 1) % 7
                if candidate.day not in doms and cron_dow not in dowss:
                    candidate += timedelta(days=1)
                    continue
        elif dom_restricted:
            if candidate.day not in doms:
                candidate += timedelta(days=1)
                continue
        elif dow_restricted:
            cron_dow = (candidate.weekday() + 1) % 7
            if cron_dow not in dowss:
                candidate += timedelta(days=1)
                continue

        # Check hour
        if candidate.hour not in hours:
            # Skip to next valid hour
            candidate = _skip_to_next_hour(candidate, hours)
            continue

        # Check minute
        if candidate.minute not in minutes:
            candidate += timedelta(minutes=1)
            continue

        return candidate

    raise ValueError("No matching time found within search range")


def parse_field(field_str: str, field_index: int):
    """Parse a single cron field and return a set of valid values."""
    # Define ranges for each field
    ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day-of-month
        (1, 12),   # month
        (0, 6),    # day-of-week (0=Sunday)
    ]

    lo, hi = ranges[field_index]
    result = set()

    for part in field_str.split(','):
        part = part.strip()
        if not part:
            raise ValueError(f"Empty part in field {field_index}")

        # Handle step values
        if '/' in part:
            base, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value '{step_str}'")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")

            if base == '*':
                start, end = lo, hi
            elif '-' in base:
                a, b = base.split('-', 1)
                try:
                    start, end = int(a), int(b)
                except ValueError:
                    raise ValueError(f"Invalid range '{base}'")
                if not (lo <= start <= end <= hi):
                    raise ValueError(f"Range {start}-{end} out of bounds [{lo}, {hi}]")
            else:
                try:
                    start = int(base)
                except ValueError:
                    raise ValueError(f"Invalid value '{base}'")
                if not (lo <= start <= hi):
                    raise ValueError(f"Value {start} out of bounds [{lo}, {hi}]")
                end = hi

            for v in range(start, end + 1, step):
                result.add(v)
        elif '-' in part:
            a, b = part.split('-', 1)
            try:
                start, end = int(a), int(b)
            except ValueError:
                raise ValueError(f"Invalid range '{part}'")
            if not (lo <= start <= end <= hi):
                raise ValueError(f"Range {start}-{end} out of bounds [{lo}, {hi}]")
            for v in range(start, end + 1):
                result.add(v)
        elif part == '*':
            result.update(range(lo, hi + 1))
        else:
            try:
                val = int(part)
            except ValueError:
                raise ValueError(f"Invalid value '{part}'")
            if not (lo <= val <= hi):
                raise ValueError(f"Value {val} out of bounds [{lo}, {hi}]")
            result.add(val)

    return result


def _skip_to_next_month(candidate, valid_months):
    """Skip to the first day of the next valid month."""
    year = candidate.year
    for _ in range(48):  # At most 4 years
        m = (candidate.month % 12) + 1
        if m == 1:
            year += 1
        if m in valid_months:
            return datetime(year, m, 1, 0, 0)
    raise ValueError("No valid month found")


def _skip_to_next_hour(candidate, valid_hours):
    """Skip to the next valid hour on the same day or later."""
    for h in range(candidate.hour + 1, 24):
        if h in valid_hours:
            return candidate.replace(hour=h, minute=0)

    # No more valid hours today; skip to next day at earliest valid hour
    min_hour = min(valid_hours)
    next_day = candidate.date() + timedelta(days=1)
    return datetime(next_day.year, next_day.month, next_day.day, min_hour, 0)

