def wildcard_match(pattern: str, s: str) -> bool:
    m = len(s)
    n = len(pattern)

    # dp[i][j] means whether pattern[:i] matches s[:j]
    dp = [[False] * (m + 1) for _ in range(n + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns like "****" matching empty string
    for i in range(1, n + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if pattern[i - 1] == '?':
                # '?' matches exactly one character
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                # '*' matches zero or more characters
                # Zero characters: dp[i-1][j], one or more: dp[i][j-1]
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            else:
                # Exact character match
                dp[i][j] = dp[i - 1][j - 1] and pattern[i - 1] == s[j - 1]

    return dp[n][m]
