class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.num_components = n
        self.history = []  # Stack of changes made by union operations

    def find(self, x):
        while x != self.parent[x]:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        # Union by size: attach smaller tree to larger tree
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        # Now root_a has >= size than root_b; attach root_b under root_a
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.num_components -= 1

        # Record the change for rollback: (child_root, parent_root)
        self.history.append((root_b, root_a))

        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child, parent = self.history.pop()
            # Undo the union: detach child from parent
            self.parent[child] = child
            self.size[parent] -= self.size[child]
            self.num_components += 1

    def components(self):
        return self.num_components
