    def __init__(self):
        self.root = {}
        self.word_counts = {}  # Track how many times each word is added

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['#'] = node.get('#', 0) + 1

        # Track word counts for removal logic
        self.word_counts[word] = self.word_counts.get(word, 0) + 1

    def remove(self, word):
        if word not in self.word_counts or self.word_counts[word] == 0:
            return False

        node = self.root
        # First check if the word exists and decrement count
        for char in word:
            if char not in node:
                return False
            node = node[char]

        if '#' not in node or node['#'] <= 0:
            return False

        node['#'] -= 1
        self.word_counts[word] -= 1

        # If count reaches zero, we need to clean up the trie path if no other words use it
        if node['#'] == 0:
            del node['#']

        # Clean up empty nodes from leaf upward (only if this was the last occurrence)
        self._clean_path(word)

        return True

    def _clean_path(self, word):
        """Remove nodes that are no longer needed after a word removal."""
        stack = []
        node = self.root
        for char in word:
            stack.append((node, char))
            node = node[char]

        # Traverse back up and remove empty nodes
        while stack:
            parent, char = stack.pop()
            child_node = parent[char]

            # Check if this child node is now useless (no '#' marker and no children)
            has_children = any(k != '#' for k in child_node.keys())
            has_word_marker = '#' in child_node

            if not has_children and not has_word_marker:
                del parent[char]
            else:
                # Stop cleaning up this path since there's still something useful here
                break

    def search(self, pattern):
        results = []
        self._dfs_search(self.root, pattern, 0, "", results)
        return sorted(results)

    def _dfs_search(self, node, pattern, idx, current_word, results):
