        if not intervals:
            return []
        # Filter out empty intervals
        valid = [(s, e) for s, e in intervals if s < e]
        if not valid:
            return []
        # Sort by start, then by end
        valid.sort()
        merged = [valid[0]]
        for s, e in valid[1:]:
            last_s, last_e = merged[-1]
            if s <= last_e:
                merged[-1] = (last_s, max(last_e, e))
            else:
                merged.append((s, e))
