def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    neg = False
    if n < 0:
        neg = True
        n = -n

    digits = []
    while n > 0:
        n, rem = divmod(n, len(alphabet))
        digits.append(alphabet[rem])

    result = ''.join(reversed(digits))
    if neg:
        result = '-' + result
    return result


def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    # Build a lookup map for characters to their values
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}

    neg = False
    start = 0

    if s[0] == '-':
        neg = True
        start = 1

    if start >= len(s):
        raise ValueError("Invalid string")

    result = 0
    for ch in s[start:]:
        if ch not in char_to_val:
            raise ValueError(f"Character '{ch}' not in alphabet")
        result = result * len(alphabet) + char_to_val[ch]

    if neg:
        result = -result

    return result
