import heapq
from collections import defaultdict


def topo_lex(graph):
    # graph maps a node to the list of nodes that depend on it (successors)
    # We need to build in-degree counts and adjacency for reverse direction

    all_nodes = set()
    for u, successors in graph.items():
        all_nodes.add(u)
        for v in successors:
            all_nodes.add(v)

    if not all_nodes:
        return []

    # Build in-degree map and reverse adjacency (for when we remove edges)
    in_degree = defaultdict(int)
    adj = defaultdict(list)  # adj[u] contains nodes that depend on u

    for u, successors in graph.items():
        for v in successors:
            adj[u].append(v)
            in_degree[v] += 1

    # Initialize heap with all nodes having in-degree 0
    zero_in = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(zero_in, node)

    result = []

    while zero_in:
        u = heapq.heappop(zero_in)
        result.append(u)

        # For each successor of u, decrease its in-degree
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(zero_in, v)

    if len(result) != len(all_nodes):
        return None

    return result
