module.exports = function createStore(reducer, initial) {
  let state = initial;
  const listeners = [];
  let isDispatching = false;

  return {
    getState() {
      return state;
    },
    dispatch(action) {
      if (isDispatching) {
        throw new Error('Dispatching from inside a reducer is not allowed');
      }
      const previousListeners = listeners.slice();
      isDispatching = true;
      try {
        state = reducer(state, action);
      } finally {
        isDispatching = false;
      }
      for (const listener of previousListeners) {
        listener();
      }
    },
    subscribe(fn) {
      listeners.push(fn);
      return () => {
        const index = listeners.indexOf(fn);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      };
    }
  };
};
