type ParamNames<T extends string> = T extends `${infer _}:${infer Name}/${infer Rest}`
  ? Name | ParamNames<`/${Rest}`>
  : T extends `${infer _}:${infer Name}`
    ? Name
    : never;

type ParamsObject<T extends string> = {
  [K in ParamNames<T>]: string;
};

export function defineRoutes<Routes extends Record<string, string>>(
  routes: Routes
): {
  [K in keyof Routes]: Routes[K] extends `${infer _}:${string}`
    ? (params: ParamsObject<Routes[K]>) => string
    : () => string;
} {
  return Object.fromEntries(
    Object.entries(routes).map(([name, path]) => {
      const hasParams = path.includes(':');
      if (!hasParams) {
        return [name, () => path];
      } else {
        return [
          name,
          (params: Record<string, string>) => {
            let result = path;
            for (const key in params) {
              result = result.replace(`:${key}`, params[key]);
            }
            return result;
          },
        ];
      }
    })
  ) as ReturnType<typeof defineRoutes<Routes>>;
}
