export type DeepPartial<T> = T extends Function | Array<unknown>
  ? T
  : T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function applyPatch<T extends object>(base: T, patch: DeepPartial<T>): T {
  if (!isObject(patch)) {
    return base;
  }

  const result = { ...base };

  for (const key of Object.keys(patch) as Array<keyof T & string>) {
    const patchValue = patch[key];

    // Treat explicit undefined in the patch as 'leave alone'
    if (patchValue === undefined) {
      continue;
    }

    const baseValue = result[key];

    // Replace arrays wholesale
    if (Array.isArray(patchValue)) {
      (result as any)[key] = [...patchValue];
    } else if (isObject(baseValue) && isObject(patchValue)) {
      // Recursively merge objects
      (result as any)[key] = applyPatch(baseValue, patchValue);
    } else {
      // For primitives or non-object types, assign directly
      (result as any)[key] = patchValue;
    }
  }

  return result;
}

